class LmdbSailStoreEstimatorPersistenceTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:persistence:predicate");

	@Test
	void versionEightSnapshotRestartsWithStableIdentity(@TempDir File dataDir) throws Exception {
		QuadSnapshotIdentity writtenIdentity;
		LmdbStore writer = open(dataDir);
		try {
			addRows(writer, 3);
			assertTrue(writer.forceFlushSketchEstimator());
			SketchBasedJoinEstimator estimator = writer.getBackingStore().getSketchBasedJoinEstimator();
			assertEquals(3.0d, predicateRows(estimator));
			writtenIdentity = estimator.quadSnapshotIdentity();
		} finally {
			writer.shutDown();
		}

		Path snapshot = snapshot(dataDir);
		assertTrue(Files.isRegularFile(snapshot));

		LmdbStore reader = open(dataDir);
		try {
			assertTrue(reader.awaitSketchesReady(10, TimeUnit.SECONDS));
			SketchBasedJoinEstimator estimator = reader.getBackingStore().getSketchBasedJoinEstimator();
			assertEquals(writtenIdentity.storeIdHigh(), estimator.quadSnapshotIdentity().storeIdHigh());
			assertEquals(writtenIdentity.storeIdLow(), estimator.quadSnapshotIdentity().storeIdLow());
			assertEquals(3.0d, predicateRows(estimator));
			assertEquals(3L, exactStatementCount(reader));
		} finally {
			reader.shutDown();
		}
	}

	@Test
	void corruptPayloadRebuildsFromLmdbWithoutChangingResults(@TempDir File dataDir) throws Exception {
		QuadSnapshotIdentity writtenIdentity;
		LmdbStore writer = open(dataDir);
		try {
			addRows(writer, 4);
			assertTrue(writer.forceFlushSketchEstimator());
			writtenIdentity = writer.getBackingStore().getSketchBasedJoinEstimator().quadSnapshotIdentity();
		} finally {
			writer.shutDown();
		}

		Path snapshot = snapshot(dataDir);
		byte[] bytes = Files.readAllBytes(snapshot);
		bytes[bytes.length - Long.BYTES - 1] ^= 0x5a;
		Files.write(snapshot, bytes);

		LmdbStore reader = open(dataDir);
		try {
			assertTrue(reader.forceFlushSketchEstimator());
			SketchBasedJoinEstimator estimator = reader.getBackingStore().getSketchBasedJoinEstimator();
			assertNotNull(estimator);
			assertEquals(writtenIdentity.storeIdHigh(), estimator.quadSnapshotIdentity().storeIdHigh());
			assertEquals(writtenIdentity.storeIdLow(), estimator.quadSnapshotIdentity().storeIdLow());
			assertEquals(4.0d, predicateRows(estimator));
			assertEquals(4L, exactStatementCount(reader));
		} finally {
			reader.shutDown();
		}
	}

	@Test
	void noneIsolationRollbackKeepsReadyEstimatorWhenPendingRowNeverPublishes(@TempDir File dataDir) {
		LmdbStore store = open(dataDir);
		try {
			addRows(store, 1);
			assertTrue(store.forceFlushSketchEstimator());
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			estimator.setRebuildAllowedSupplier(() -> false);
			assertTrue(estimator.isReadyNonBlocking());
			long checkpointsBefore = store.getBackingStore().noneIngestionMetrics().checkpoints();
			IRI pending = VF.createIRI("urn:persistence:pending-rollback");
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				connection.addStatement(pending, PREDICATE, VF.createLiteral("pending"));
				assertEquals(checkpointsBefore, store.getBackingStore().noneIngestionMetrics().checkpoints(),
						"a single default-bulk row must stay in the pending batch");
				connection.rollback();
			}
			assertTrue(estimator.isReadyNonBlocking(),
					"discarding an unpublished pending row must not invalidate the ready estimator");
			assertEquals(1.0d, predicateRows(estimator), 0.0d,
					"the ready unified snapshot must contain only the committed seed row");
			try (NotifyingSailConnection connection = store.getConnection()) {
				assertFalse(connection.hasStatement(pending, PREDICATE, null, false));
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void directSinkCommitAfterRollbackIsVisibleToNativeAndConnectionReads(@TempDir File dataDir) {
		LmdbStore store = open(dataDir);
		try {
			addRows(store, 1);
			assertTrue(store.forceFlushSketchEstimator());
			LmdbSailStore backingStore = store.getBackingStore();
			IRI rolledBack = VF.createIRI("urn:persistence:direct-rollback");
			IRI committed = VF.createIRI("urn:persistence:direct-after-rollback");
			try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED)) {
				sink.approve(rolledBack, PREDICATE, VF.createLiteral("rolled-back"), null);
				backingStore.rollback();
			}
			try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED)) {
				sink.approve(committed, PREDICATE, VF.createLiteral("committed"), null);
				sink.flush();
			}
			try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE);
					CloseableIteration<? extends Statement> rows = dataset.getStatements(committed, PREDICATE, null)) {
				assertTrue(rows.hasNext(), "native reads must see the direct sink commit after rollback");
				assertEquals(committed, rows.next().getSubject());
				assertFalse(rows.hasNext());
			}
			try (NotifyingSailConnection connection = store.getConnection()) {
				assertTrue(connection.hasStatement(committed, PREDICATE, null, false));
				assertFalse(connection.hasStatement(rolledBack, PREDICATE, null, false));
			}
			assertTrue(store.forceFlushSketchEstimator());
			assertEquals(2.0d, predicateRows(backingStore.getSketchBasedJoinEstimator()), 0.0d);
			assertEquals(2L, exactStatementCount(store));
		} finally {
			store.shutDown();
		}
	}

	private static LmdbStore open(File dataDir) {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc")
				.setSketchEstimatorEnabled(true)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L));
		store.init();
		return store;
	}

	private static void addRows(LmdbStore store, int count) {
		try (NotifyingSailConnection connection = store.getConnection()) {
			connection.begin();
			for (int index = 0; index < count; index++) {
				connection.addStatement(VF.createIRI("urn:persistence:s" + index), PREDICATE,
						VF.createLiteral(index));
			}
			connection.commit();
		}
	}

	private static long exactStatementCount(LmdbStore store) {
		long count = 0L;
		try (NotifyingSailConnection connection = store.getConnection();
				CloseableIteration<? extends Statement> statements = connection.getStatements(null, null, null,
						false)) {
			while (statements.hasNext()) {
				statements.next();
				count++;
			}
		}
		return count;
	}

	private static double predicateRows(SketchBasedJoinEstimator estimator) {
		QuadProbe probe = new QuadProbe(QuadProbe.PREDICATE, QuadProbe.OBJECT, 0L,
				QuadValueHash.hash(PREDICATE), 0L, 0L, estimator.quadSnapshotIdentity());
		return estimator.synopsisService().probe(probe).rows().estimate();
	}

	private static Path snapshot(File dataDir) {
		return dataDir.toPath().resolve("join-estimator.rjes/synopsis-v8.bin");
	}
}
